WITH base AS (SELECT * FROM accounts WHERE opened_date >= '2024-01-01'), summary AS (SELECT account_type, COUNT(DISTINCT balance) AS unique_statuss, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(account_type))) AS account_type_values FROM base GROUP BY account_type) SELECT account_type, account_type_values FROM summary WHERE unique_statuss >= 8 ORDER BY account_type, account_type_values LIMIT 3;
